import RNA
import random
import sys
import multiprocessing as mp

target = "(((((((((((((((((...(.(..((.(((.(((.((....).))).)))).).)..))..))))))).(((((..(.(..((.(((.(((((.(((.((((.((....).)))).))))).))).)))).).)..))..)((....))..))))(((((((((...))))).(((((...)))))(.(....).).)))).)))).((((.((((...(((((((...))))))).(((((...)))))))))(((((((...))))))).(((((...)))))))))((((..((....))(..((..(..(.(.(((.((((.((....).)))).)))).)..)..).))..))))).)))))).".strip()
n = len(target)

stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

paired = [i in pairs for i in range(n)]

def init_seq(rng):
    seq = [None]*n
    for i in range(n):
        if seq[i] is not None:
            continue
        if paired[i]:
            j = pairs[i]
            if i < j:
                r = rng.random()
                if r < 0.55:
                    a,b = 'G','C'
                elif r < 0.75:
                    a,b = 'C','G'
                elif r < 0.85:
                    a,b = 'A','U'
                elif r < 0.95:
                    a,b = 'U','A'
                else:
                    a,b = 'G','U'
                seq[i] = a
                seq[j] = b
        else:
            seq[i] = rng.choice("AAUC")
    return seq

def fold(seq):
    s = "".join(seq)
    struct, mfe = RNA.fold(s)
    return struct, mfe

def bp_distance(s1, s2):
    return RNA.bp_distance(s1, s2)

def run_restart(seed_steps):
    seed, STEPS = seed_steps
    rng = random.Random(seed)
    seq = init_seq(rng)
    struct, mfe = fold(seq)
    cur_dist = bp_distance(struct, target)
    best_seq = seq.copy()
    best_dist = cur_dist
    T0 = 2.0
    for step in range(STEPS):
        T = T0 * (1 - step/STEPS) + 0.01
        i = rng.randrange(n)
        old = seq[i]
        oldj = None
        if paired[i]:
            j = pairs[i]
            r = rng.random()
            if r < 0.5:
                a,b = 'G','C'
            elif r < 0.7:
                a,b = 'C','G'
            elif r < 0.85:
                a,b = 'A','U'
            elif r < 0.95:
                a,b = 'U','A'
            else:
                a,b = 'G','U'
            oldj = seq[j]
            seq[i] = a
            seq[j] = b
        else:
            seq[i] = rng.choice("ACGU")

        new_struct, new_mfe = fold(seq)
        new_dist = bp_distance(new_struct, target)

        accept = False
        if new_dist <= cur_dist:
            accept = True
        else:
            try:
                p = pow(2.71828, -(new_dist-cur_dist)/T)
            except OverflowError:
                p = 0.0
            if rng.random() < p:
                accept = True

        if accept:
            cur_dist = new_dist
            struct = new_struct
        else:
            seq[i] = old
            if paired[i]:
                seq[j] = oldj

        if cur_dist < best_dist:
            best_dist = cur_dist
            best_seq = seq.copy()
            if best_dist == 0:
                break
    return best_dist, "".join(best_seq)

if __name__ == "__main__":
    NPROC = 16
    STEPS = 6000
    tasks = [(seed, STEPS) for seed in range(NPROC)]
    with mp.Pool(NPROC) as pool:
        results = pool.map(run_restart, tasks)
    results.sort(key=lambda x: x[0])
    for dist, seq in results:
        print(dist, seq)
    print("BEST:", results[0])

